std::vector<std::uint8_t>Data(GuardedDeviceBuffer&b,std::size_t n){return Payload(b.ReadAll(),n);}std::vector<std::uint8_t>Concat(std::initializer_list<std::pair<GuardedDeviceBuffer*,std::size_t>>parts){std::vector<std::uint8_t>r;for(auto&p:parts){auto x=Data(*p.first,p.second);r.insert(r.end(),x.begin(),x.end());}return r;}
void Rec(const std::filesystem::path&p,const std::string&id,std::uint8_t poison,const c::ExternalInputs&before,const c::ExternalInputs&after,const std::array<std::vector<std::uint8_t>,13>&w0,const std::array<std::vector<std::uint8_t>,13>&b0,const std::array<std::vector<std::uint8_t>,13>&w1,const std::array<std::vector<std::uint8_t>,13>&b1,const std::array<std::string,16>&ch,const std::vector<std::uint8_t>&out,std::size_t mm,std::size_t can){std::ofstream s(p);bool pass=mm==0&&can==0;s<<"{\n  \"schema\": \"neuralstudio.fg.connected-custom-l56-l71-run.v1\",\n  \"backend\": \"rtx-cuda-driver\",\n  \"run_id\": \""<<id<<"\",\n  \"process_id\": "<<GetCurrentProcessId()<<",\n  \"poison_byte\": "<<unsigned(poison)<<",\n  \"launch_range\": [56, 71],\n  \"launch_count\": 16,\n  \"checkpoint_sha256\": {";for(int i=0;i<16;++i)s<<(i?", ":"\n    ")<<"\"launch-"<<std::setfill('0')<<std::setw(6)<<(56+i)<<"\": \""<<ch[i]<<"\"";s<<"\n  },\n  \"external_input_generator\": \"splitmix64-fg-connected-custom-l56-l71-v1\",\n  \"external_input_pre_sha256\": [\""<<Sha256(before.a)<<"\", \""<<Sha256(before.b)<<"\", \""<<Sha256(before.c)<<"\"],\n  \"external_input_post_sha256\": [\""<<Sha256(after.a)<<"\", \""<<Sha256(after.b)<<"\", \""<<Sha256(after.c)<<"\"],\n  \"model_manifest_sha256\": \""<<c::kManifestSha256<<"\",\n  \"module_state\": [";for(std::size_t i=0;i<c::kModules.size();++i)s<<(i?",":"")<<"{\"module_token\":"<<c::kModules[i].token<<",\"module_sha256\":\""<<c::kModules[i].sha<<"\"}";s<<"],\n  \"model_state\": [";for(std::size_t i=0;i<c::kModels.size();++i){auto&m=c::kModels[i];s<<(i?",":"")<<"{\"weight_token\":"<<m.weight_token<<",\"weight_sha256\":\""<<Sha256(w0[i])<<"\",\"bias_token\":"<<m.bias_token<<",\"bias_sha256\":\""<<Sha256(b0[i])<<"\"}";}s<<"],\n  \"model_state_post_sha256\": [";for(std::size_t i=0;i<c::kModels.size();++i)s<<(i?",":"")<<"[\""<<Sha256(w1[i])<<"\",\""<<Sha256(b1[i])<<"\"]";s<<"],\n  \"final_output_sha256\": \""<<Sha256(out)<<"\",\n  \"final_output_bytes\": "<<out.size()<<",\n  \"input_model_mismatched_bytes\": "<<mm<<",\n  \"canary_mismatched_bytes\": "<<can<<",\n  \"in_process_handoff_count\": 15,\n  \"archived_intermediate_ingress\": false,\n  \"expected_output_file_opened\": false,\n  \"address_fields_recorded\": false,\n  \"result\": \""<<(pass?"pass":"fail")<<"\"\n}\n";}
