CUdeviceptr p_l56=l56.payload(),pa=a.payload(),pb=b.payload(),pc=scalar.payload();std::uint32_t h=368,w=640;float factor=.5f;void*initArgs[]={&p_l56,&pa,&pb,&pc,&h,&w,&factor};Check(cuLaunchKernel(fn[0],40,23,1,16,16,1,0,nullptr,initArgs,nullptr),"l56");
